import{_ as a,o as i,c as r,ai as o}from"./chunks/framework.ampVZV4B.js";const _=JSON.parse('{"title":"TypeScript 面试","description":"","frontmatter":{},"headers":[],"relativePath":"guide/nodejs/typescript-interview.md","filePath":"guide/nodejs/typescript-interview.md"}'),c={name:"guide/nodejs/typescript-interview.md"};function l(t,e,n,d,s,h){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="typescript-面试" tabindex="-1">TypeScript 面试 <a class="header-anchor" href="#typescript-面试" aria-label="Permalink to “TypeScript 面试”">​</a></h1><hr><h2 id="高频问法" tabindex="-1">高频问法 <a class="header-anchor" href="#高频问法" aria-label="Permalink to “高频问法”">​</a></h2><ol><li>为什么项目要上 TypeScript？</li><li><code>interface</code> vs <code>type</code>？</li><li><code>any</code> / <code>unknown</code> / <code>never</code>？</li><li>联合类型、类型守卫？</li><li>泛型解决什么问题？</li><li>枚举和字面量联合？</li><li><code>tsconfig</code> 里你关心哪些选项？</li><li>如何和 Vue/Java 后端接口对齐类型？</li></ol><hr><h2 id="口述参考" tabindex="-1">口述参考 <a class="header-anchor" href="#口述参考" aria-label="Permalink to “口述参考”">​</a></h2><h3 id="_1-为什么用-ts" tabindex="-1">1）为什么用 TS <a class="header-anchor" href="#_1-为什么用-ts" aria-label="Permalink to “1）为什么用 TS”">​</a></h3><p>编译期发现错误、重构安全、接口即文档、协作成本低。<br> 代价：要写类型、有时要与不完备的 <code>.d.ts</code> 斗争——业务项目通常值得。</p><h3 id="_2-interface-vs-type" tabindex="-1">2）interface vs type <a class="header-anchor" href="#_2-interface-vs-type" aria-label="Permalink to “2）interface vs type”">​</a></h3><p>描述对象两者都行。<br><code>type</code> 擅长联合、交叉、映射；<code>interface</code> 可声明合并。<br> 团队统一即可，面试别教条。</p><h3 id="_3-any-unknown-never" tabindex="-1">3）any / unknown / never <a class="header-anchor" href="#_3-any-unknown-never" aria-label="Permalink to “3）any / unknown / never”">​</a></h3><ul><li><code>any</code>：关闭检查，能不用就不用</li><li><code>unknown</code>：安全的「未知」，用前要收窄</li><li><code>never</code>：不该有值的分支（穷尽检查）</li></ul><h3 id="_4-联合与守卫" tabindex="-1">4）联合与守卫 <a class="header-anchor" href="#_4-联合与守卫" aria-label="Permalink to “4）联合与守卫”">​</a></h3><p><code>string | number</code>；用 <code>typeof</code> / <code>in</code> / 自定义谓词收窄。<br> 处理后端「成功 | 失败」结果类型很常见。</p><h3 id="_5-泛型" tabindex="-1">5）泛型 <a class="header-anchor" href="#_5-泛型" aria-label="Permalink to “5）泛型”">​</a></h3><p>组件/函数保留类型信息：<code>function first&lt;T&gt;(arr: T[]): T</code>。<br> Axios 封装 <code>request&lt;T&gt;()</code> 返回 <code>Promise&lt;T&gt;</code> 是好例子。</p><h3 id="_6-枚举" tabindex="-1">6）枚举 <a class="header-anchor" href="#_6-枚举" aria-label="Permalink to “6）枚举”">​</a></h3><p>可用 <code>enum</code>，也可用 <code>as const</code> + 字面量联合（更轻）。<br> 知道两种都能做「有限集合」即可。</p><h3 id="_7-tsconfig-常提" tabindex="-1">7）tsconfig 常提 <a class="header-anchor" href="#_7-tsconfig-常提" aria-label="Permalink to “7）tsconfig 常提”">​</a></h3><ul><li><code>strict</code>（或逐步开 <code>strictNullChecks</code>）</li><li><code>module</code> / <code>moduleResolution</code></li><li><code>paths</code> 别名</li><li><code>skipLibCheck</code> 有时用于加速，但别当忽略一切错误的借口</li></ul><h3 id="_8-与后端对齐" tabindex="-1">8）与后端对齐 <a class="header-anchor" href="#_8-与后端对齐" aria-label="Permalink to “8）与后端对齐”">​</a></h3><ul><li>后端 OpenAPI → 生成 TS 类型；或手写 DTO 与 Java VO 字段对齐</li><li>日期、枚举、可空字段最容易不一致——联调清单里要写明</li></ul><hr><h2 id="追问预备" tabindex="-1">追问预备 <a class="header-anchor" href="#追问预备" aria-label="Permalink to “追问预备”">​</a></h2><ul><li>「类型擦除？」→ TS 编译后运行时无类型，别指望靠类型做运行时校验；运行时用 zod 等或手写校验。</li><li>「装饰器？」→ 知道实验性/用于 Nest 等；Electron+Vue 项目未必用到。</li></ul>',25)])])}const f=a(c,[["render",l]]);export{_ as __pageData,f as default};
